using JTradeERP.Application.Common.Exceptions;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Security;using MediatR;
namespace JTradeERP.Application.Features.Inventory.WarehouseNegativeStock.UpdateWarehouseNegativeStockSetting;
public sealed class UpdateWarehouseNegativeStockSettingHandler(IApplicationDbContext db,ICurrentUserService actor):IRequestHandler<UpdateWarehouseNegativeStockSettingCommand,UpdateWarehouseNegativeStockSettingResponse>
{ public async Task<UpdateWarehouseNegativeStockSettingResponse> Handle(UpdateWarehouseNegativeStockSettingCommand r,CancellationToken ct){var w=db.Warehouses.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Warehouse was not found.");var old=w.AllowNegativeStock;w.SetAllowNegativeStock(r.AllowNegativeStock);SecurityAuditWriter.Add(db,actor.UserId,"WarehouseNegativeStockSettingChanged","Warehouse",w.Id.ToString(),old.ToString(),r.AllowNegativeStock.ToString());await db.SaveChangesAsync(ct);return new(w.Id,w.WarehouseCode,w.AllowNegativeStock);} }
